/**
 * The mock site data the atlas draws.
 *
 * Right now every site is SYNTHETIC (apps/atlas/mock/sites/*.json, generated by
 * apps/atlas/mock/generate_mock.py). Real data replaces these files when the
 * ingest lane (#19) and the engine lane (#20) land.
 */

import type { Site } from "./types";

const modules = import.meta.glob("../mock/sites/*.json", { eager: true }) as Record<
  string,
  { default: Site }
>;

export const SITES: Site[] = Object.values(modules)
  .map((module) => module.default)
  .sort((a, b) => a.siteId.localeCompare(b.siteId));

export function siteById(siteId: string): Site | undefined {
  return SITES.find((site) => site.siteId === siteId);
}

/** The readiness entry of one site for one objective, if there is one. */
export function readinessFor(site: Site, objectiveId: string) {
  return site.readiness?.find((entry) => entry.objectiveId === objectiveId);
}
